        //
        // Ingress:
        //      aEarthLaneD (-->), aEarthLaneB (-->), pCrossLaneB (<-?->)
        //
        // Cross:
        //      aEarthLaneC (<--), aEarthLaneA (<--), aSource (<-?->)
        //
