            aCross = (RotL64(aEarthLaneC[((S_BLOCK1 - aIndex + 3670U)) & S_BLOCK1], 37U) ^ RotL64(aEarthLaneA[((S_BLOCK1 - aIndex + 3184U)) & S_BLOCK1], 21U));
            aCross ^= RotL64(aSource[((aIndex + 1993U)) & S_BLOCK1], 60U);
