            aOrbiterA = (aOrbiterA + aOrbiterK) + 0xB7107AE9F0A03034ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterA) ^ 0xF87EF424BE021C10ULL) ^ aOUSaltF[(((511U - aIndex) + 179U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x96E7B6103A67BCC9ULL), 13U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterA) + 0x09616267C6A1B614ULL) + aOUSaltE[(((511U - aIndex) + 391U)) & S_SALT1];
