            //
            aOrbiterA = ((aWandererE + RotL64(aPrevious, 13U)) + 0x1BD4FEB97CF45D54ULL) + aOASaltC[(((511U - aIndex) + 12U)) & S_SALT1];
            aOrbiterH = (((aWandererB + RotL64(aCross, 34U)) + RotL64(aCarry, 43U)) + 0x20D5021F270A83CCULL) + aOASaltH[((aIndex + 341U)) & S_SALT1];
