            aOrbiterC = (((aWandererJ + RotL64(aPrevious, 5U)) + RotL64(aCarry, 13U)) + 0xAE0B4BCA78B5C3BEULL) + aOASaltD[((aIndex + 192U)) & S_SALT1];
            aOrbiterK = ((aWandererG + RotL64(aScatter, 43U)) + 0x2A3471F845D6E663ULL) + aOASaltA[((aIndex + 259U)) & S_SALT1];
